import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 21 Daniel Mendoza","description":"学习 完成时不定式的先后关系，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 21 Daniel Mendoza","description":"学习 完成时不定式的先后关系，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 完成时不定式的先后关系，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 20 Pioneer pilots","link":"/life/english/new-concept/book-3/unit-01/lesson-020"},"next":{"text":"第三册：培养技能 · Lesson 22 By heart","link":"/life/english/new-concept/book-3/unit-02/lesson-022"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 20 Pioneer pilots","link":"/life/english/new-concept/book-3/unit-01/lesson-020"},"next":{"text":"第三册：培养技能 · Lesson 22 By heart","link":"/life/english/new-concept/book-3/unit-02/lesson-022"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-021.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-021.md"}'),o={name:"life/english/new-concept/book-3/unit-02/lesson-021.md"};function l(s,e,r,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第三册-培养技能-·-lesson-21-daniel-mendoza" tabindex="-1">第三册：培养技能 · Lesson 21 Daniel Mendoza <a class="header-anchor" href="#第三册-培养技能-·-lesson-21-daniel-mendoza" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 21 Daniel Mendoza&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以人物生涯与职业规则变化为主题，练习选取有解释力的经历而不是堆积年代。人物取得成绩与后来生活困难可以同在一段文字里，但需要连接清楚。学习完成时不定式表达比主句更早的动作，同时区分公众声誉与可以核实的经历。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>champion</td><td>/ˈtʃæmpiən/</td><td>n.</td><td>冠军</td><td>a former champion</td></tr><tr><td>defeat</td><td>/dɪˈfiːt/</td><td>v.</td><td>击败</td><td>defeat an opponent</td></tr><tr><td>discipline</td><td>/ˈdɪsəplɪn/</td><td>n.</td><td>纪律</td><td>strict discipline</td></tr><tr><td>legacy</td><td>/ˈleɡəsi/</td><td>n.</td><td>遗产或影响</td><td>a lasting legacy</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>rise to fame — 成名</li><li>fall into debt — 陷入债务</li></ul><h2 id="语法讲解-完成时不定式的先后关系" tabindex="-1">语法讲解：完成时不定式的先后关系 <a class="header-anchor" href="#语法讲解-完成时不定式的先后关系" aria-label="Permalink to &quot;语法讲解：完成时不定式的先后关系&quot;">​</a></h2><p>to have 加过去分词表示不定式动作早于主句参照时间，常见于 seem、appear、be said 等结构。He seems to have left 表示现在看来他此前已经离开；He seemed to have left 则把观察点也放在过去。to do 通常表示同时状态或随后动作，不能一概理解为将来。be said to 仅说明有人这样说，不等于事实已获证实。写人物传记时，要用时间状语或来源说明限制推断，不能让复杂结构代替证据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The retired athlete appears to have inspired a new generation of coaches.</p></blockquote><p>这位退役运动员似乎已经启发了新一代教练。</p><p>appears 为现在判断，to have inspired 指此前发生并留下影响的行为。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>He seems to won 不成立；强调此前获胜应写 seems to have won，描述经常获胜则可用 seems to win。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 appears to have inspired，弱读 to 和 have，但保留 inspired 的重音，听是否仍能识别完成结构。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Elena won her first regional title at nineteen. She seems to have influenced several younger runners. Two of them now use the training diary she designed.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句写虚构运动员的小传，包含可见成绩、谨慎评价和具体影响。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>事实先行，谨慎评价后接具体证据，避免空泛赞扬。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句的启发发生在判断之前还是之后？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 之前。</p><p><strong>解析：</strong> 完成时不定式表示更早的动作。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改正：She is said to has retired.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She is said to have retired.</p><p><strong>解析：</strong> to 后 have 用原形。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>be said to 是否保证消息为真？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不保证。</p><p><strong>解析：</strong> 它标明转述状态而非证据充分程度。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：完成时不定式的先后关系。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-020">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-022">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
